quickStart:
-- Extract a simple value
SELECT jsonata('Account', '{"Account": 5}');

-- Concatenate fields with the . operator
SELECT jsonata('FirstName & " " & Surname',
  '{"FirstName":"Fred","Surname":"Smith"}') AS r;

-- Reshape JSON — pull only the fields you need
SELECT jsonata('{ "name": FirstName & " " & Surname, "mobile": Phone[type="mobile"].number }', payload) AS extracted
FROM contacts;
